import json
import collections
import heapq

# Retrieve parameters directly from the globally injected 'input_data' dictionary
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

def solve_safari_path(map_id, start_x, start_y, target_x, target_y):
    width, height = 30, 25
    if map_id == "0_218": # North is 40x36
        width, height = 40, 36
    elif map_id == "0_220": # Center is 30x27
        width, height = 30, 27

    def is_plateau_tile(mx, my):
        if map_id == "0_219": # West
            if 11 <= mx <= 23 and 6 <= my <= 19:
                return True
            if 6 <= mx <= 10 and 16 <= my <= 19:
                return True
            return False
        elif map_id == "0_217": # East
            if 11 <= mx <= 22 and 6 <= my <= 20:
                return True
            return False
        elif map_id == "0_218": # North
            if 18 <= mx <= 24 and 20 <= my <= 22:
                return True
            if 28 <= mx <= 34 and 15 <= my <= 27:
                return True
            return False
        return False

    static_ground_obstacles = set()

    if map_id == "0_219": # West
        for x in range(10, 14):
            for y in range(8, 12):
                static_ground_obstacles.add((x, y))
        static_ground_obstacles.add((12, 12))
        for x in range(2, 10):
            for y in range(10, 14):
                static_ground_obstacles.add((x, y))
        for y in range(11, 16):
            static_ground_obstacles.add((14, y))
            static_ground_obstacles.add((15, y))
        for y in range(1, 14):
            static_ground_obstacles.add((24, y))
        for y in range(14, 18):
            static_ground_obstacles.add((23, y))
        static_ground_obstacles.add((1, 13))
        static_ground_obstacles.add((1, 14))
        static_ground_obstacles.add((1, 15))
        static_ground_obstacles.add((4, 16))
        static_ground_obstacles.add((4, 17))
        static_ground_obstacles.add((4, 18))
        static_ground_obstacles.add((4, 19))
        for y in range(height):
            static_ground_obstacles.add((0, y))

    elif map_id == "0_217": # East
        for x in range(5, 9):
            for y in range(21, 24):
                static_ground_obstacles.add((x, y))
        for x in range(0, 11):
            static_ground_obstacles.add((x, 6))
        for x in range(16, 20):
            for y in range(16, 18):
                static_ground_obstacles.add((x, y))

    elif map_id == "0_218": # North
        for x in range(10, 20):
            static_ground_obstacles.add((x, 34))
            static_ground_obstacles.add((x, 35))
        for y in range(11, 35):
            static_ground_obstacles.add((17, y))

    elif map_id == "0_220": # Center
        for x in range(13, 15):
            static_ground_obstacles.add((x, 22))
        static_ground_obstacles.add((15, 24))
        for x in range(0, 18):
            static_ground_obstacles.add((x, 15))
            static_ground_obstacles.add((x, 16))
        for x in range(22, 28):
            static_ground_obstacles.add((x, 9))
        for x in range(8, 22):
            for y in range(8, 14):
                static_ground_obstacles.add((x, y))

    start_states = []
    if is_plateau_tile(start_x, start_y):
        start_states.append((start_x, start_y, 1))
    if (start_x, start_y) not in static_ground_obstacles:
        start_states.append((start_x, start_y, 0))

    grass_tiles = set()
    if map_id == "0_219": # West
        for y in range(18, 21):
            grass_tiles.add((3, y))

    queue = []
    for sz in start_states:
        heapq.heappush(queue, (0, start_x, start_y, sz, []))

    visited = {}

    while queue:
        cost, cx, cy, cz, path = heapq.heappop(queue)

        if (cx, cy) == (target_x, target_y):
            return path

        state_key = (cx, cy, cz)
        if state_key in visited and visited[state_key] <= cost:
            continue
        visited[state_key] = cost

        moves = [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]
        for dx, dy, move in moves:
            nx, ny, nz = cx + dx, cy + dy, cz

            if map_id == "0_219": # West
                if (cx, cy, cz) == (6, 20, 0) and move == "Up":
                    nx, ny, nz = 6, 19, 1
                elif (cx, cy, cz) == (6, 18, 1) and move == "Down":
                    nx, ny, nz = 6, 19, 1
                elif (cx, cy, cz) == (6, 19, 1) and move == "Down":
                    nx, ny, nz = 6, 20, 0
                elif (cx, cy, cz) == (21, 18, 0) and move == "Up":
                    nx, ny, nz = 21, 17, 1
                elif (cx, cy, cz) == (21, 16, 1) and move == "Down":
                    nx, ny, nz = 21, 17, 1
                elif (cx, cy, cz) == (21, 17, 1) and move == "Down":
                    nx, ny, nz = 21, 18, 0

            elif map_id == "0_217": # East
                if (cx, cy, cz) == (20, 22, 0) and move == "Up":
                    nx, ny, nz = 20, 21, 1
                elif (cx, cy, cz) == (20, 20, 1) and move == "Down":
                    nx, ny, nz = 20, 21, 1
                elif (cx, cy, cz) == (20, 21, 1) and move == "Down":
                    nx, ny, nz = 20, 22, 0
                elif (cx, cy, cz) == (10, 20, 0) and move == "Right":
                    nx, ny, nz = 11, 20, 1
                elif (cx, cy, cz) == (12, 20, 1) and move == "Left":
                    nx, ny, nz = 11, 20, 1
                elif (cx, cy, cz) == (11, 20, 1) and move == "Left":
                    nx, ny, nz = 10, 20, 0
                elif (cx, cy, cz) == (12, 8, 0) and move == "Up":
                    nx, ny, nz = 12, 7, 1
                elif (cx, cy, cz) == (12, 6, 1) and move == "Down":
                    nx, ny, nz = 12, 7, 1
                elif (cx, cy, cz) == (12, 7, 1) and move == "Down":
                    nx, ny, nz = 12, 8, 0
                elif (cx, cy, cz) == (17, 8, 0) and move == "Up":
                    nx, ny, nz = 17, 7, 1
                elif (cx, cy, cz) == (17, 6, 1) and move == "Down":
                    nx, ny, nz = 17, 7, 1
                elif (cx, cy, cz) == (17, 7, 1) and move == "Down":
                    nx, ny, nz = 17, 8, 0

            elif map_id == "0_218": # North
                if (cx, cy, cz) == (22, 24, 0) and move == "Up":
                    nx, ny, nz = 22, 23, 1
                elif (cx, cy, cz) == (22, 22, 1) and move == "Down":
                    nx, ny, nz = 22, 23, 1
                elif (cx, cy, cz) == (22, 23, 1) and move == "Down":
                    nx, ny, nz = 22, 24, 0
                elif (cx, cy, cz) == (16, 28, 0) and move == "Up":
                    nx, ny, nz = 16, 27, 1
                elif (cx, cy, cz) == (16, 26, 1) and move == "Down":
                    nx, ny, nz = 16, 27, 1
                elif (cx, cy, cz) == (16, 27, 1) and move == "Down":
                    nx, ny, nz = 16, 28, 0
                elif (cx, cy, cz) == (28, 28, 0) and move == "Up":
                    nx, ny, nz = 28, 27, 1
                elif (cx, cy, cz) == (28, 26, 1) and move == "Down":
                    nx, ny, nz = 28, 27, 1
                elif (cx, cy, cz) == (28, 27, 1) and move == "Down":
                    nx, ny, nz = 28, 28, 0
                elif (cx, cy, cz) == (34, 14, 0) and move == "Up":
                    nx, ny, nz = 34, 15, 1
                elif (cx, cy, cz) == (34, 16, 1) and move == "Down":
                    nx, ny, nz = 34, 15, 1
                elif (cx, cy, cz) == (34, 15, 1) and move == "Down":
                    nx, ny, nz = 34, 14, 0

            if not (0 <= nx < width and 0 <= ny < height):
                continue

            if nz == 0:
                if is_plateau_tile(nx, ny):
                    is_transition = False
                    if map_id == "0_219":
                        is_transition = ((cx, cy, cz) == (6, 20, 0) and (nx, ny, nz) == (6, 19, 1)) or ((cx, cy, cz) == (21, 18, 0) and (nx, ny, nz) == (21, 17, 1))
                    elif map_id == "0_217":
                        is_transition = ((cx, cy, cz) == (20, 22, 0) and (nx, ny, nz) == (20, 21, 1)) or ((cx, cy, cz) == (10, 20, 0) and (nx, ny, nz) == (11, 20, 1)) or ((cx, cy, cz) == (12, 8, 0) and (nx, ny, nz) == (12, 7, 1)) or ((cx, cy, cz) == (17, 8, 0) and (nx, ny, nz) == (17, 7, 1))
                    elif map_id == "0_218":
                        is_transition = ((cx, cy, cz) == (22, 24, 0) and (nx, ny, nz) == (22, 23, 1)) or ((cx, cy, cz) == (16, 28, 0) and (nx, ny, nz) == (16, 27, 1)) or ((cx, cy, cz) == (28, 28, 0) and (nx, ny, nz) == (28, 27, 1)) or ((cx, cy, cz) == (34, 14, 0) and (nx, ny, nz) == (34, 15, 1))
                    if not is_transition:
                        continue
                if (nx, ny) in static_ground_obstacles:
                    continue
            else:
                if not is_plateau_tile(nx, ny):
                    is_transition = False
                    if map_id == "0_219":
                        is_transition = ((cx, cy, cz) == (6, 19, 1) and (nx, ny, nz) == (6, 20, 0)) or ((cx, cy, cz) == (21, 17, 1) and (nx, ny, nz) == (21, 18, 0))
                    elif map_id == "0_217":
                        is_transition = ((cx, cy, cz) == (20, 21, 1) and (nx, ny, nz) == (20, 22, 0)) or ((cx, cy, cz) == (11, 20, 1) and (nx, ny, nz) == (10, 20, 0)) or ((cx, cy, cz) == (12, 7, 1) and (nx, ny, nz) == (12, 8, 0)) or ((cx, cy, cz) == (17, 7, 1) and (nx, ny, nz) == (17, 8, 0))
                    elif map_id == "0_218":
                        is_transition = ((cx, cy, cz) == (22, 23, 1) and (nx, ny, nz) == (22, 24, 0)) or ((cx, cy, cz) == (16, 27, 1) and (nx, ny, nz) == (16, 28, 0)) or ((cx, cy, cz) == (28, 27, 1) and (nx, ny, nz) == (28, 28, 0)) or ((cx, cy, cz) == (34, 15, 1) and (nx, ny, nz) == (34, 14, 0))
                    if not is_transition:
                        continue

            move_cost = 10 if (nx, ny) in grass_tiles else 1
            heapq.heappush(queue, (cost + move_cost, nx, ny, nz, path + [move]))

    return None

path = solve_safari_path(map_id, start_x, start_y, target_x, target_y)
if path is not None:
    print(json.dumps(path))
else:
    print(json.dumps([]))
